#include <iostream>
#include <vector>
#include <string>
#include <cstdio>
#include <cstring>
using namespace std;

int main() {
    FILE* fin = fopen("/workdir/data/parking.txt", "r");
    FILE* fout = fopen("/workdir/answer.txt", "w");

    int n, m;
    fscanf(fin, "%d %d", &n, &m);
    char buf[10];
    fscanf(fin, "%s", buf); // consume possible leftover

    vector<string> grid(n);
    for (int i = 0; i < n; i++) {
        grid[i].resize(m);
        fscanf(fin, "%s", grid[i].data());
    }

    // Compute up[r][c] = consecutive '.' going upward from (r,c)
    vector<vector<int>> up(n, vector<int>(m, 0));
    for (int c = 0; c < m; c++) {
        int cnt = 0;
        for (int r = 0; r < n; r++) {
            if (grid[r][c] == '.') cnt++;
            else cnt = 0;
            up[r][c] = cnt;
        }
    }

    vector<vector<long long>> ans(n + 1, vector<long long>(m + 1, 0));

    for (int h = 1; h <= n; h++) {
        vector<int> cnt(m + 1, 0); // cnt[L] = number of runs of length L at height h
        bool any = false;
        for (int r = 0; r < n; r++) {
            int run = 0;
            for (int c = 0; c < m; c++) {
                if (up[r][c] >= h) {
                    run++;
                } else {
                    if (run > 0) {
                        cnt[run]++;
                        any = true;
                        run = 0;
                    }
                }
            }
            if (run > 0) {
                cnt[run]++;
                any = true;
            }
        }

        if (!any) continue;

        // Compute suffix sums and fill ans[h][w]
        long long sc = 0, slc = 0;
        for (int w = m; w >= 1; w--) {
            sc += cnt[w];
            slc += (long long)cnt[w] * (w + 1);
            ans[h][w] = slc - (long long)w * sc;
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (j > 1) fprintf(fout, " ");
            fprintf(fout, "%lld", ans[i][j]);
        }
        fprintf(fout, "\n");
    }

    fclose(fin);
    fclose(fout);
    return 0;
}
